def load_snapshot():
    compressed = base64.b64decode("".join(PAYLOAD_B64))
    actual = hashlib.sha256(compressed).hexdigest()
    if actual != PAYLOAD_SHA256:
        raise RuntimeError(f"Embedded snapshot checksum mismatch: {actual}")
    snapshot = json_util.loads(gzip.decompress(compressed).decode("utf-8"))
    return migrate_snapshot_form_configs(snapshot)


def safe_storage_path(root: Path, relative: str) -> Path:
    root = root.resolve()
    target = (root / relative.lstrip("/")).resolve()
    if target != root and root not in target.parents:
        raise RuntimeError(f"Unsafe storage path in snapshot: {relative}")
    return target


async def verify(db, snapshot, storage_root: Path):
    errors = []
    expected_collections = snapshot["collections"]
    for name, documents in expected_collections.items():
        actual = await db[name].count_documents({})
        if actual != len(documents):
            errors.append(f"{name} count: expected {len(documents)}, got {actual}")

    users = {str(d["_id"]): d for d in await db.users.find({}).to_list(100000)}
    partners = {str(d["_id"]): d for d in await db.partners.find({}).to_list(100000)}
    steps = {str(d["_id"]): d for d in await db.steps.find({}).to_list(100000)}
    files = {d.get("id"): d for d in await db.files.find({}).to_list(100000)}

    async for row in db.user_progress.find({}):
        if row.get("user_id") not in users:
            errors.append(f"orphan progress user {row.get('user_id')}")
        if row.get("step_id") not in steps:
            errors.append(f"orphan progress step {row.get('step_id')}")
    async for row in db.partner_submissions.find({}):
        if row.get("user_id") not in users:
            errors.append(f"orphan submission user {row.get('user_id')}")
        if row.get("partner_id") not in partners:
            errors.append(f"orphan submission partner {row.get('partner_id')}")

    if len(files) != len(snapshot["file_blobs"]):
        errors.append("file metadata/blob mapping count mismatch")
    for storage_path, expected_sha in snapshot["file_blobs"].items():
        path = safe_storage_path(storage_root, storage_path)
        if not path.is_file():
            errors.append(f"missing upload object {storage_path}")
        elif hashlib.sha256(path.read_bytes()).hexdigest() != expected_sha:
            errors.append(f"upload checksum mismatch {storage_path}")

    duplicate_emails = [k for k, n in Counter(
        (u.get("email") or "").lower() for u in users.values()
    ).items() if n > 1]
    if duplicate_emails:
        errors.append(f"duplicate emails: {duplicate_emails}")

    if errors:
        print(f"Baseline verification FAILED ({len(errors)} errors)")
        for error in errors[:100]:
            print(f"  - {error}")
        return False
    counts = {name: len(documents) for name, documents in expected_collections.items()}
    print("Baseline verification OK")
    print(counts)
    print(f"upload_objects={len(snapshot['file_blobs'])}, unique_blobs={len(snapshot['blobs'])}")
    return True


async def main():
    parser = argparse.ArgumentParser(description="Restore or verify the canonical IHCA baseline")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--force", action="store_true", help="drop DB_NAME and restore the embedded baseline")
    mode.add_argument("--verify-only", action="store_true", help="verify without changing data")
    args = parser.parse_args()

    mongo_url = os.environ["MONGO_URL"]
    db_name = os.environ["DB_NAME"]
    storage_value = os.environ.get("LOCAL_STORAGE_ROOT", "").strip()
    if not storage_value:
        raise RuntimeError("LOCAL_STORAGE_ROOT is required for the baseline upload objects")
    storage_root = Path(storage_value)
    snapshot = load_snapshot()
    client = AsyncIOMotorClient(mongo_url)
    db = client[db_name]

    if args.verify_only:
        ok = await verify(db, snapshot, storage_root)
        client.close()
        raise SystemExit(0 if ok else 1)

    print(f"Restoring baseline created at {SNAPSHOT_CREATED_AT}")
    print(f"Dropping MongoDB database {db_name!r} and replacing {storage_root}")
    await client.drop_database(db_name)
    db = client[db_name]
    for name, documents in snapshot["collections"].items():
        if documents:
            await db[name].insert_many(documents, ordered=True)
        print(f"  {name}: {len(documents)}")

    await db.users.create_index("email", unique=True)
    await db.surveys.create_index("slug", unique=True)
    await db.password_reset_tokens.create_index("expires_at", expireAfterSeconds=0)
    await db.login_attempts.create_index("identifier")

    storage_root.mkdir(parents=True, exist_ok=True)
    # LOCAL_STORAGE_ROOT may itself be a Docker volume mount. Removing the
    # mountpoint fails with EBUSY; clear only its contents instead.
    for child in storage_root.iterdir():
        if child.is_dir() and not child.is_symlink():
            shutil.rmtree(child)
        else:
            child.unlink()
    blobs = {sha: base64.b64decode(data) for sha, data in snapshot["blobs"].items()}
    for relative, sha in snapshot["file_blobs"].items():
        target = safe_storage_path(storage_root, relative)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(blobs[sha])

    ok = await verify(db, snapshot, storage_root)
    client.close()
    if not ok:
        raise SystemExit(1)
    print("Canonical baseline restored successfully")


if __name__ == "__main__":
    asyncio.run(main())
